#include "resident/kernel/catalog_section_observation.hpp"
#include "resident/domains/growth/growth_model.hpp"
// 明示安全住宿/合格医馆是Installed设施合同，独立于原rest体力收益；活动条款仍由Growth原账负责。
#include "growth_recovery_qualification.hpp"
#include <algorithm>
#include <set>
#include <limits>
namespace hanmo::resident {namespace {
std::size_t pos(const CommonStore& c,const StableId& id){const auto& ids=c.state().facts.order();return std::size_t(std::find(ids.begin(),ids.end(),id)-ids.begin());}
void unique(const BoundaryValue& v,Integer depth=0){if(depth>16)boundary::fail("RecoveryCatalogTooDeep","");if(const auto* object=v.as<BoundaryValue::Dict>()){std::set<StableId> keys;for(const auto& row:*object){if(!keys.insert(row.first).second)boundary::fail("DuplicateRecoveryCatalogField",row.first);unique(row.second,depth+1);}}else if(const auto* array=v.as<BoundaryValue::Array>())for(const auto& item:*array)unique(item,depth+1);}
Status free(const Outcome<MilitaryActorOccupation>& read,const StableId& actor,Integer tick,const StableId& boundary){if(!read.ok)return {false,{},read.error};const auto& r=read.value;if(r.actor_id!=actor||r.observed_tick!=tick||r.boundary_fact_id!=boundary)return common_failure("GrowthRecoveryOccupationSourceMismatch",actor);if(!r.history_complete||!r.incomplete_source_ids.empty())return common_failure("GrowthRecoveryOccupationHistoryUnavailable",actor);if(!r.custody_source_ids.empty()||!r.battle_source_ids.empty()||!r.siege_source_ids.empty())return common_failure("GrowthRecoveryMilitaryOccupied",actor);return common_success();}
// 仅已实际接受的那份原life服务能够提供具体双方与起始地点，不根据今天的岗位持有人猜旧合同。
Outcome<StableId> original(const CommonStore& c,const CommonCatalog& shared,const GrowthCatalog& growth,const GrowthRecoveryCatalog& catalog,const GrowthState& state,const GrowthRecoveryService& service,const StableId& action_id){auto valid=validate_growth_recovery_catalog(shared,growth,catalog);if(!valid.ok)return {false,{},valid.error};const auto* method=catalog.service_roles.find(service.role_id);const auto* role=shared.roles.find(service.role_id);if(!method||*method!=service.method||!role||role->place_id!=service.place_id)return {false,{},common_failure("GrowthRecoveryFacilityMismatch",service.role_id).error};const auto* r=state.life_activities.find(action_id);const auto* head=c.state().facts.find(action_id);const auto* terms=r?std::get_if<ServiceTerms>(&r->terms):nullptr;
if(!r||!head||!terms||head->kind!="life_activity"||head->domain!="growth"||r->view.action_id!=action_id||r->view.fact_id!=action_id||r->view.actor_id!=service.actor_id||r->view.provider_actor_id!=service.provider_actor_id||r->view.start_tick!=service.start_tick||r->context.role_id!=service.role_id||r->view.kind!=LifeActivityKind::service||r->view.activity!="rest"||terms->duration!=service.duration||r->context.place_id!=service.place_id)return {false,{},common_failure("GrowthRecoveryOriginalServiceRequired",action_id).error};return {true,action_id,{}};}
}
Status validate_growth_recovery_catalog(const CommonCatalog& shared,const GrowthCatalog& growth,const GrowthRecoveryCatalog& catalog){
  // 只旁观本次原入口；返回值与首错仍由原函数独占。
  ::hanmo::resident::catalog_section_observation::Scope catalog_cost_observation(
      ::hanmo::resident::catalog_section_observation::Kind::catalog_validation, 45, "GrowthRecoveryCatalog", "validate_growth_recovery_catalog", &catalog);
if(!growth.regional_life||catalog.service_roles.empty()||catalog.service_roles.size()>256)return common_failure("GrowthRecoveryCatalogInvalid");for(const auto& row:catalog.service_roles.rows()){const auto* role=shared.roles.find(row.first);const auto* place=role?shared.places.find(role->place_id):nullptr;const auto* offering=growth.roles.find(row.first);const auto* terms=offering?offering->activities.find("rest"):nullptr;if(!role||!place||!terms||std::find(role->services.begin(),role->services.end(),"rest")==role->services.end()||growth_recovery_service_points(row.second)<1||terms->duration<1||terms->duration>720||terms->cost<0||terms->wage!=0||terms->wallet_id.empty())return common_failure("GrowthRecoveryFacilityInvalid",row.first);}return common_success();}
Outcome<GrowthRecoveryCatalog> decode_growth_recovery_catalog(const BoundaryValue& v,const CommonCatalog& shared,const GrowthCatalog& growth){try{using namespace boundary;unique(v);fields(v,{"version","services"},{},"personal_injury_recovery");if(get_int(v,"version","")!=1)fail("UnsupportedGrowthRecoveryVersion","");GrowthRecoveryCatalog out;for(const auto& row:array(field(v,"services",""),"services")){fields(row,{"role_id","method"},{},"service");const auto role=get_string(row,"role_id","service"),method=get_string(row,"method","service");if(method!="safe_lodging"&&method!="qualified_clinic")fail("InvalidGrowthRecoveryMethod",role);if(!out.service_roles.insert(role,method=="safe_lodging"?GrowthRecoveryMethod::safe_lodging:GrowthRecoveryMethod::qualified_clinic))fail("DuplicateGrowthRecoveryFacility",role);}auto valid=validate_growth_recovery_catalog(shared,growth,out);if(!valid.ok)return {false,{},valid.error};return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status validate_growth_recovery_occupation_now(const CommonStore& c,const GrowthRecoveryOccupationRead& access,const StableId& actor,const DynamicStepInput* phase){
    if(c.tick()<0||(phase&&(c.tick()==std::numeric_limits<Integer>::max()||phase->from_tick!=c.tick()||phase->to_tick!=c.tick()+1)))return common_failure("GrowthRecoveryPhaseInvalid",actor);
    if(!access.current)return common_failure("GrowthRecoveryOccupationReaderRequired");
    return free(access.current(actor),actor,phase?phase->to_tick:c.tick(),{});
}
static Status qualification_now(const CommonStore& c,const CommonCatalog& shared,const GrowthCatalog& growth,const GrowthRecoveryCatalog& catalog,const GrowthState& state,const GrowthRecoveryOccupationRead& access,const GrowthRecoveryService& service,const DynamicStepInput* phase){const auto* patient=c.actor(service.actor_id);auto source=original(c,shared,growth,catalog,state,service,patient?patient->action_id:StableId{});if(!source.ok)return {false,{},source.error};if(!access.current)return common_failure("GrowthRecoveryOccupationReaderRequired");const auto* assignment=c.state().roles.find(service.role_id);const auto* action=c.action(source.value);if(!assignment||assignment->actor_id!=service.provider_actor_id||!action||action->kind!="service"||action->actor_id!=service.actor_id)return common_failure("GrowthRecoveryCurrentServiceMismatch",source.value);for(const auto* id:{&service.actor_id,&service.provider_actor_id}){const auto* person=c.actor(*id);auto location=c.resolved_location(*id);const auto* at=location.ok?std::get_if<SettlementLocation>(&location.value):nullptr;if(!person||!person->alive||!person->available||person->action_id!=source.value||!at||at->place_id!=service.place_id||std::find(action->participants.begin(),action->participants.end(),*id)==action->participants.end())return common_failure("GrowthRecoveryServiceNotPresent",*id);auto clear=validate_growth_recovery_occupation_now(c,access,*id,phase);if(!clear.ok)return clear;}return common_success();}
Status validate_growth_recovery_qualification_now(const CommonStore& c,const CommonCatalog& shared,const GrowthCatalog& growth,const GrowthRecoveryCatalog& catalog,const GrowthState& state,const GrowthRecoveryOccupationRead& access,const GrowthRecoveryService& service){return qualification_now(c,shared,growth,catalog,state,access,service,nullptr);}
Status validate_growth_recovery_qualification_now(const CommonStore& c,const CommonCatalog& shared,const GrowthCatalog& growth,const GrowthRecoveryCatalog& catalog,const GrowthState& state,const GrowthRecoveryOccupationRead& access,const GrowthRecoveryService& service,const DynamicStepInput& phase){return qualification_now(c,shared,growth,catalog,state,access,service,&phase);}
Status validate_growth_recovery_qualification_before(const CommonStore& c,const CommonCatalog& shared,const GrowthCatalog& growth,const GrowthRecoveryCatalog& catalog,const GrowthState& state,const GrowthRecoveryState& recovery,const GrowthRecoveryOccupationRead& access,const GrowthRecoveryService& service,Integer tick,const StableId& boundary){const auto* credit=recovery.credits.find(boundary);auto source=original(c,shared,growth,catalog,state,service,credit?credit->action_id:StableId{});if(!source.ok)return {false,{},source.error};const auto* head=c.state().facts.find(boundary);const auto* original_record=state.life_activities.find(source.value);if(!head||head->kind!="personal_recovery_credit"||head->domain!="personal_injury_recovery"||!credit||credit->action_id!=source.value||credit->tick!=tick||pos(c,source.value)>=pos(c,boundary)||tick<=service.start_tick||tick-service.start_tick>service.duration||!original_record||(original_record->view.phase!=LifeActivityPhase::active&&tick>original_record->view.completed_tick))return common_failure("GrowthRecoveryQualificationBoundaryMismatch",boundary);if(!access.before)return common_failure("GrowthRecoveryOccupationReaderRequired");for(const auto* actor:{&service.actor_id,&service.provider_actor_id}){auto clear=free(access.before(*actor,tick,boundary),*actor,tick,boundary);if(!clear.ok)return clear;}return common_success();}
}
